<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import UiIcon from '@/components/ui/UiIcon.vue'
import type { useAiFleet } from '@/composables/aiFleet'

type FleetApi = ReturnType<typeof useAiFleet>
const props = defineProps<{ fleet: FleetApi }>()
const activeId = ref('')
const reconcileSummary = ref('')
const reconcileOutcome = ref<'succeeded' | 'failed' | 'manual_recovery' | 'retry'>('manual_recovery')
const reconcileGrant = ref('')
const grantOptions = [{ value: '', label: 'No high-impact action' }, { value: 'reboot:reboot', label: 'Allow one reboot' }, { value: 'file_write:push', label: 'Allow one file push' }, { value: 'file_write:pull', label: 'Allow one file pull' }, { value: 'apk_install:install', label: 'Allow one APK install' }]
const selected = computed(() => props.fleet.selectedJob.value)
const jobs = computed(() => props.fleet.jobs.value)
const checkpoints = computed(() => (selected.value?.checkpoints || selected.value?.children?.flatMap(child => child.checkpoints || []) || []).filter(Boolean))
function stateLabel(state?: string) { return String(state || 'unknown').replaceAll('_', ' ') }
function stateClass(state?: string) { return `is-${String(state || 'unknown').replaceAll('_', '-')}` }
async function openJob(jobId: string) { activeId.value = jobId; await props.fleet.loadJob(jobId) }
async function act(action: 'pause' | 'resume' | 'stop' | 'retry') { if (selected.value) await props.fleet.actionJob(selected.value.job_id, action) }
async function reconcile(childId: string) { if (reconcileOutcome.value !== 'retry' && !reconcileSummary.value.trim()) return; if (!reconcileSummary.value.trim()) reconcileSummary.value = 'Owner approved retry'; const [capability, operation] = reconcileGrant.value.split(':'); await props.fleet.reconcile(childId, reconcileOutcome.value, reconcileSummary.value, reconcileOutcome.value === 'retry' && capability && operation ? { capability, operation } : undefined); reconcileSummary.value = ''; reconcileGrant.value = '' }
onMounted(() => { if (jobs.value[0]) void openJob(jobs.value[0].job_id) })
</script>

<template>
  <section class="ui-panel fleet-monitor" aria-labelledby="monitor-heading">
    <div class="fleet-monitor__head"><div><span class="ui-eyebrow">05 · Monitor</span><h3 id="monitor-heading">Fleet jobs and owner checkpoints</h3></div><span class="ui-badge ui-badge--muted">{{ jobs.length }} job{{ jobs.length === 1 ? '' : 's' }}</span></div>
    <div v-if="!jobs.length" class="ui-empty"><strong>No approved fleet jobs</strong><span>Plan approval creates a durable parent job. Local preview never dispatches a phone action.</span></div>
    <div v-else class="fleet-monitor__layout">
      <div class="fleet-job-list" role="list" aria-label="Fleet jobs"><button v-for="job in jobs" :key="job.job_id" type="button" class="fleet-job-row" :class="{ 'is-selected': job.job_id === activeId }" @click="openJob(job.job_id)"><span class="fleet-job-row__id">{{ job.job_id.slice(0, 10) }}</span><span class="fleet-job-row__state" :class="stateClass(job.state)">{{ stateLabel(job.state) }}</span><span class="fleet-job-row__count">{{ job.completed_count || 0 }}/{{ job.target_count || 0 }}</span></button></div>
      <div v-if="selected" class="fleet-job-detail">
        <div class="fleet-job-detail__head"><div><span class="ui-label">Job {{ selected.job_id }}</span><p class="ui-hint">{{ selected.completed_count || 0 }} completed · {{ selected.uncertain_count || 0 }} uncertain · budget reserved ${{ Number(selected.budget_reserved_usd || 0).toFixed(2) }}</p></div><span class="ui-badge" :class="stateClass(selected.state)">{{ stateLabel(selected.state) }}</span></div>
        <div class="fleet-monitor__actions"><button type="button" class="ui-btn ui-btn--sm" :disabled="selected.state !== 'running'" @click="act('pause')">Pause</button><button type="button" class="ui-btn ui-btn--sm ui-btn--danger" :disabled="['stopped','cancelled','succeeded'].includes(selected.state)" @click="act('stop')">Stop</button><button type="button" class="ui-btn ui-btn--sm" :disabled="!['paused', 'waiting_for_owner'].includes(selected.state)" @click="act('resume')">Resume</button><button type="button" class="ui-btn ui-btn--sm" :disabled="selected.state !== 'failed'" @click="act('retry')">Retry safe failures</button></div>
        <div class="fleet-children"><article v-for="child in selected.children || []" :key="child.child_id || child.serial" class="fleet-child"><div class="fleet-child__head"><strong>{{ child.label || child.serial || child.target_id || 'Target' }}</strong><span class="ui-badge" :class="stateClass(child.state)">{{ stateLabel(child.state || child.phase) }}</span></div><p class="ui-hint">{{ child.latest_action || 'Waiting for worker evidence' }} · {{ child.retries || 0 }} retries<span v-if="child.evidence_at"> · evidence {{ child.evidence_at }}</span></p><ol v-if="child.receipts?.length" class="fleet-timeline"><li v-for="receipt in child.receipts" :key="`${receipt.created_at}-${receipt.capability}`"><span class="fleet-timeline__dot" aria-hidden="true"></span><span><strong>{{ receipt.capability || 'step' }}</strong> {{ receipt.summary || receipt.outcome || 'recorded' }}<small>{{ receipt.created_at || 'time not reported' }}</small></span></li></ol><div v-if="['uncertain', 'manual_recovery', 'waiting_for_owner'].includes(String(child.state))" class="fleet-reconcile"><span class="ui-label">{{ child.state === 'waiting_for_owner' ? 'This phone is waiting for you: approve and retry, or close it' : 'Uncertain result requires owner reconciliation' }}</span><div class="fleet-monitor__actions"><select v-model="reconcileOutcome" aria-label="Reconciliation outcome"><option value="retry">Approve and retry</option><option value="manual_recovery">Keep manual recovery</option><option value="succeeded">Verified succeeded</option><option value="failed">Verified failed</option></select><select v-if="reconcileOutcome === 'retry'" v-model="reconcileGrant" aria-label="One-time owner grant"><option v-for="option in grantOptions" :key="option.value" :value="option.value">{{ option.label }}</option></select><input v-model="reconcileSummary" maxlength="240" placeholder="Evidence summary (no raw screen or secret)" aria-label="Reconciliation summary" /><button type="button" class="ui-btn ui-btn--sm" :disabled="reconcileOutcome !== 'retry' && !reconcileSummary.trim()" @click="reconcile(child.child_id || child.serial || '')">Reconcile</button></div></div></article></div>
        <div v-if="checkpoints.length" class="fleet-checkpoints" aria-live="polite"><span class="ui-label">Pending owner checkpoints</span><div v-for="checkpoint in checkpoints" :key="checkpoint?.checkpoint_id" class="fleet-checkpoint"><UiIcon name="alert" :size="14" /><span>{{ checkpoint?.reason || 'Owner input required' }}<small>{{ checkpoint?.capability || 'checkpoint' }} · {{ checkpoint?.created_at || 'time not reported' }}</small></span></div></div>
      </div>
    </div>
  </section>
</template>

<style scoped>
.fleet-monitor { padding:15px; }.fleet-monitor__head,.fleet-job-detail__head { display:flex; justify-content:space-between; gap:12px; align-items:start; }.fleet-monitor__layout { display:grid; grid-template-columns:220px minmax(0,1fr); gap:14px; margin-top:10px; }.fleet-job-list { display:grid; align-content:start; gap:5px; }.fleet-job-row { display:grid; grid-template-columns:1fr auto auto; gap:7px; align-items:center; width:100%; padding:9px; text-align:left; border:1px solid var(--ui-border); border-radius:var(--ui-radius-sm); color:var(--ui-text-2); background:var(--ui-surface-sunken); cursor:pointer; }.fleet-job-row:hover,.fleet-job-row.is-selected { border-color:var(--ui-accent-line); background:var(--ui-accent-soft); }.fleet-job-row__id { font-family:var(--ui-mono); font-size:10px; }.fleet-job-row__state,.fleet-job-row__count { font-size:10px; white-space:nowrap; }.fleet-job-row__state { color:var(--ui-accent); }.fleet-job-detail { min-width:0; }.fleet-monitor__actions { display:flex; gap:7px; flex-wrap:wrap; margin:10px 0; }.ui-btn--danger { color:#ffaaa7; border-color:rgba(255,100,100,.35); }.fleet-children { display:grid; gap:8px; }.fleet-child { padding:10px; border:1px solid var(--ui-border); border-radius:var(--ui-radius-sm); }.fleet-child__head { display:flex; justify-content:space-between; gap:8px; }.fleet-timeline { list-style:none; margin:9px 0 0; padding:0 0 0 3px; display:grid; gap:8px; }.fleet-timeline li { display:flex; gap:8px; font-size:11px; color:var(--ui-text-2); }.fleet-timeline small,.fleet-checkpoint small { display:block; color:var(--ui-text-4); font-size:10px; margin-top:2px; }.fleet-timeline__dot { width:7px; height:7px; margin:4px 0 0; border-radius:50%; background:var(--ui-accent); flex:none; }.fleet-reconcile { margin-top:10px; padding:9px; background:rgba(245,158,11,.08); border:1px solid rgba(245,158,11,.28); border-radius:var(--ui-radius-sm); }.fleet-reconcile input,.fleet-reconcile select { min-height:32px; padding:5px 7px; }.fleet-checkpoints { display:grid; gap:7px; margin-top:12px; padding-top:12px; border-top:1px solid var(--ui-border); }.fleet-checkpoint { display:flex; align-items:flex-start; gap:8px; padding:8px; color:#f6c76d; border:1px solid rgba(245,158,11,.28); border-radius:var(--ui-radius-sm); background:rgba(245,158,11,.06); }.fleet-checkpoint span { font-size:11px; }.fleet-checkpoint small { display:block; color:var(--ui-text-4); }.is-running,.is-succeeded { color:var(--ui-accent); }.is-failed,.is-uncertain,.is-manual-recovery,.is-waiting-for-owner { color:#f6c76d; }
@media (max-width:760px) { .fleet-monitor__layout { grid-template-columns:1fr; } }
</style>
